// The acknowledgements a reader can read inside the app: generated by Tools\notices.ps1 from the shipped set and
// embedded beside the binary.
namespace XDict.App;

internal static class Notices
{
    public static string Text { get; } = Load();

    private static string Load()
    {
        using Stream? stream = typeof(Notices).Assembly.GetManifestResourceStream("XDict.App.Notices.txt");
        if (stream is null) return "The acknowledgements file is missing from this build.";
        using var reader = new StreamReader(stream);
        return reader.ReadToEnd();
    }
}
